#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""Score a slow-box timing kit: one arm against a baseline arm over a block window.

Input: the kit's per-run CSVs, plain or gzipped, named <prefix>_run<N>-<ARM>_<table>.csv[.gz] with tables
block_timing, process_info and host_sample. Optional per run: <prefix>_run<N>-<ARM>_block_timing_tail_from_log.csv[.gz]
(rows the export missed, taken from the node's log) and driver.log (the driver's stop reading of the node's CPU).

Window: from the time block H0 was added to the time block H1 was added (block_timing log_time; `height` is the true
block height). Default H0 = 3,103,300, H1 = 3,103,450: 150 blocks of one-input transactions.

Per run:
- wall: H1's log_time minus H0's;
- CPU: the node's cumulative user+system CPU seconds (process_info), interpolated linearly at both ends. If the
  samples end before the window does, the driver's stop reading (driver.log, "node cpu ticks", 1/100 s) is the last point;
- median t3 and median p/t (block_processing_ms) over blocks H0+1..H1, and the sum of p/t;
- the host's iowait share and PSI io-full seconds over the window (host_sample; clipped at the last host sample).

Summary: the arm's median over its runs divided by the baseline's median, for wall, CPU and the sum of p/t, and
whether the arm's slowest run is faster than the baseline's fastest (no overlap).

usage: slowbox_score.py <dir> <prefix> [--arm N] [--base B] [--h0 3103300] [--h1 3103450] [--runs 1,2,3,4]
"""
import argparse, csv, datetime, glob, gzip, io, os, re, statistics, sys

def open_csv(path):
    for p in (path, path + ".gz"):
        if os.path.exists(p):
            raw = gzip.open(p, "rt") if p.endswith(".gz") else open(p)
            return list(csv.DictReader(raw))
    return None

def ts(s):
    return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).timestamp()

def interp(pts, t):
    for (t1, c1), (t2, c2) in zip(pts, pts[1:]):
        if t1 <= t <= t2:
            return c1 + (c2 - c1) * (t - t1) / (t2 - t1)
    raise ValueError("time %.1f outside the samples (%.1f-%.1f)" % (t, pts[0][0], pts[-1][0]))

ap = argparse.ArgumentParser()
ap.add_argument("dir"); ap.add_argument("prefix")
ap.add_argument("--arm", default="N"); ap.add_argument("--base", default="B")
ap.add_argument("--h0", type=int, default=3103300); ap.add_argument("--h1", type=int, default=3103450)
ap.add_argument("--runs", default="", help="comma-separated run numbers to include (default: all)")
a = ap.parse_args()
keep = set(int(x) for x in a.runs.split(",") if x)
driver = ""
if os.path.exists(os.path.join(a.dir, "driver.log")):
    driver = open(os.path.join(a.dir, "driver.log")).read()

names = sorted(set(re.sub(r"\.gz$", "", os.path.basename(p)) for p in glob.glob(os.path.join(a.dir, a.prefix + "_run*_block_timing.csv*"))))
res = {}
for name in names:
    m = re.match(re.escape(a.prefix) + r"_run(\d+)-([A-Z])_block_timing\.csv$", name)
    if not m:
        continue
    num, arm = int(m.group(1)), m.group(2)
    if keep and num not in keep:
        continue
    base = os.path.join(a.dir, "%s_run%d-%s_" % (a.prefix, num, arm))
    rows = {int(r["height"]): (r["log_time"], float(r["t3_ms"]), float(r["block_processing_ms"])) for r in open_csv(base + "block_timing.csv")}
    ntail = 0
    for r in open_csv(base + "block_timing_tail_from_log.csv") or []:
        h = int(r["height"])
        if h not in rows:   # breakdown_ms: 13 fields, t3 is the fifth
            rows[h] = (r["log_time"], float(r["breakdown_ms"].split("/")[4]), float(r["block_processing_ms"])); ntail += 1
    missing = [h for h in range(a.h0, a.h1 + 1) if h not in rows]
    if missing:
        sys.exit("run %d-%s: heights missing from the window: %s" % (num, arm, missing[:10]))
    ta, tb = ts(rows[a.h0][0]), ts(rows[a.h1][0]); wall = tb - ta
    win = [rows[h] for h in range(a.h0 + 1, a.h1 + 1)]
    t3 = statistics.median(x[1] for x in win); pt = statistics.median(x[2] for x in win); ptsum = sum(x[2] for x in win) / 1000
    pi = open_csv(base + "process_info.csv"); pid = pi[0]["pid"]
    cpu_pts = [(ts(r["time"]), float(r["cpu_time_user"]) + float(r["cpu_time_system"])) for r in pi if r["pid"] == pid]
    dm = re.search(r"^(\S+?)Z? run %d arm %s: passed .* node cpu ticks (\d+)" % (num, arm), driver, re.M)
    used_driver = False
    if dm and ts(dm.group(1) + "+00:00") > cpu_pts[-1][0] and tb > cpu_pts[-1][0]:
        cpu_pts.append((ts(dm.group(1) + "+00:00"), int(dm.group(2)) / 100)); used_driver = True
    cpu = interp(cpu_pts, tb) - interp(cpu_pts, ta)
    hs = open_csv(base + "host_sample.csv")
    hb = min(tb, ts(hs[-1]["time"])); clip = tb - hb
    def hdelta(col):
        p = [(ts(r["time"]), float(r[col])) for r in hs]
        return interp(p, hb) - interp(p, ta)
    tot = sum(hdelta(c) for c in ("cpu_user", "cpu_nice", "cpu_system", "cpu_idle", "cpu_iowait", "cpu_irq", "cpu_softirq"))
    iow = hdelta("cpu_iowait") / tot; psi = hdelta("psi_io_full_us") / 1e6
    res.setdefault(arm, []).append((wall, cpu, ptsum))
    notes = []
    if ntail: notes.append("%d tail rows from the log" % ntail)
    if used_driver: notes.append("end CPU from the driver's stop reading")
    if clip > 0: notes.append("host figures end %.1f s early" % clip)
    print("run %d-%s: wall %.1f s, CPU %.1f s (%.2f cores), median t3 %.0f ms, median p/t %.0f ms, sum p/t %.1f s; host iowait %.1f%%, PSI io full %.0f s%s" % (
        num, arm, wall, cpu, cpu / wall, t3, pt, ptsum, 100 * iow, psi, ("; " + ", ".join(notes)) if notes else ""))
if a.arm not in res or a.base not in res:
    sys.exit("need runs of both arms %s and %s" % (a.arm, a.base))
for i, name in ((0, "wall"), (1, "CPU"), (2, "sum p/t")):
    b = [x[i] for x in res[a.base]]; v = [x[i] for x in res[a.arm]]
    r = statistics.median(v) / statistics.median(b)
    print("%s: %s %s; %s %s; %s/%s of medians %.3f (%+.1f%%); %s" % (
        name, a.base, " ".join("%.1f" % x for x in b), a.arm, " ".join("%.1f" % x for x in v), a.arm, a.base, r, 100 * (r - 1),
        "no overlap" if max(v) < min(b) else ("no overlap, %s slower" % a.arm if min(v) > max(b) else "overlap")))
